def string_xor(v1: str, v2: str) -> str:
    return "".join(
        (
            "1"
            if (v1[v3] == "1" and v2[v3] == "0") or (v1[v3] == "0" and v2[v3] == "1")
            else "0"
        )
        for v3 in range(len(v1))
    )
```

